INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('abysewhell','Abysewhell','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"abysewhell","name":"Abysewhell","team":"demon","ability":"From now on, nominations don''t occur & the Storyteller asks questions: wrong answers kill, correct 1s kill the winner''s choice. Evil only loses when all die.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-087 is a stairwell that further descends everyone into madness.","summaryBullets":["The process of nominations and executions have been replaced with solving questions. Players that answer incorrectly die on the spot, while players that answer correctly get to choose to who dies immediately.","Only living players can be candidates to answer a question - whats the point of a punishment if it isn''t applicable.","Players may independently choose to answer the question, or the Storyteller may call on them to answer it. Additionally, the Storyteller may impose a time limit for the player answering the question.","The good team wins if all evil players are dead, and the evil team wins if all good players are dead. However, the game doesn''t end when only two players are alive in the case that at least one evil player is still left.","The Storyteller may set a fixed amount of questions each day, or impose a variable amount each day depending on the in-game circumstances."],"howToRun":["During the nomination process for execution, declare that players cannot make nominations, but you will be giving questions. Publicly declare your question. Any living player may publicly answer it, or you may forcefully choose a player too. If their answer is wrong, they die, and you may choose to keep the current question, or declare a new one. If their answer is correct, declare that to all players, and let the winner point at player, and declare that the chosen player {{i|dies}} - put a shroud on their character token in the Grimoire. Either way the question is answered, you may choose to end the day at any time.","The Abysewhell does not lose their ability when they are drunk, poisoned, or dead, and killing the Abysewhell does not immediately end the game until all other evil players are dead {{i|(also unaffected by being drunk or poisoned)}}."],"tips":["Consider how many players you want to die each day to make the game more intense and engaging for all players. It''s recommended you aim for games that end on Day 3, 4, or 5."],"iconBy":"le_nuberto","jinxes":[{"name":"Banshee","align":"good","text":"If the Abysewhell is in play & the Banshee dies from an evil player answering their question correctly, their ability activates immediately.","id":"banshee"},{"name":"Butler","align":"good","text":"The Butler''s ability is replaced with \"Each night, choose a living player (not yourself): you become their alignment (you don''t know which.)\"","id":"butler"},{"name":"Cannibal","align":"good","text":"The Cannibal instead gains the ability of the most recent player to die to a good player answering their question correctly.","id":"cannibal"},{"name":"Devil''s Advocate","align":"evil","text":"Devil''s Advocate-protected-players cannot die by answering their question incorrectly.","id":"devilsadvocate"},{"name":"Engineer","align":"good","text":"The Engineer cannot swap out the Abysewhell.","id":"engineer"},{"name":"Evil Twin","align":"evil","text":"Only 1 jinxed character can be in play.","id":"eviltwin"},{"name":"Farmer","align":"good","text":"If the Abysewhell is in play & the Farmer dies from an evil player answering their question correctly, a good player becomes a Farmer that night.","id":"farmer"},{"name":"Fearmonger","align":"evil","text":"Only 1 jinxed character can be in play.","id":"fearmonger"},{"name":"Flowergirl","align":"good","text":"The Flower Girl instead learns if a Demon or Minion correctly answered any questions for their ability.","id":"flowergirl"},{"name":"Fortune Teller","align":"good","text":"Minions register as the Demon to the Fortune Teller.","id":"fortuneteller"},{"name":"Goblin","align":"evil","text":"If the Abysewhell is in play & the Goblin dies from a good player answering their question correctly (whilst they claimed to be the Goblin), their team wins.","id":"goblin"},{"name":"Innkeeper","align":"good","text":"Innkeeper-protected-players cannot die from players answering their question correctly.","id":"innkeeper"},{"name":"Mastermind","align":"evil","text":"The Mastermind''s ability is replaced with \"The first 2 times you answer incorrectly per day, you don''t die.\".","id":"mastermind"},{"name":"Mayor","align":"good","text":"If the Abysewhell is in play & the Mayor is one of the last two good players alive, the next two times they would''ve died, they don''t.","id":"mayor"},{"name":"Minstrel","align":"good","text":"If a Minion dies during the day, the Minstrel''s ability activates starting dusk and lasts until dusk tommorow.","id":"minstrel"},{"name":"Monk","align":"good","text":"Monk-protected-players cannot die from evil players answering their question correctly.","id":"monk"},{"name":"Pacifist","align":"good","text":"If the Pacifist is in-play, good players might not die by answering their question incorrectly.","id":"pacifist"},{"name":"Ravenkeeper","align":"good","text":"If the Abysewhell is in play & the Ravenkeeper dies during the day by a player answering their question correctly, they wake that night to use their ability. They are drunk if their killer is good.","id":"ravenkeeper"},{"name":"Sage","align":"good","text":"If the Abysewhell is in play & the Sage dies during the day by an player answering their question correctly, they wake that night to learn 2 evil players. They are drunk if their killer is good.","id":"sage"},{"name":"Saint","align":"good","text":"If the Abysewhell is in play & the Saint dies during the day by a good player answering their question correctly, their team loses.","id":"saint"},{"name":"Scarlet Woman","align":"evil","text":"If the Scarlet Woman is in-play, the first time the Abysewhell answers their question incorrectly, they are instead declared correct.","id":"scarletwoman"},{"name":"Soldier","align":"good","text":"The Soldier cannot die from evil players answering their question correctly.","id":"soldier"},{"name":"Town Crier","align":"good","text":"The Town Crier instead learns how many Minions answered any questions for their ability. If the number would be 0, they are instead drunk that night.","id":"towncrier"},{"name":"Undertaker","align":"good","text":"The Undertaker instead learns the last player to die today to a good player answering their question correctly.","id":"undertaker"},{"name":"Virgin","align":"good","text":"The first time the Virgin would die from a player answering their question correctly, if the killer is a Townsfolk, they are executed immediately.","id":"virgin"},{"name":"Vizier","align":"evil","text":"The Vizier''s ability is replaced with \"You cannot die during the day. You may suggest a question to the Storyteller they''ll use. You are not required to die for evil to lose.\".","id":"vizier"},{"name":"Witch","align":"evil","text":"Witch-cursed players die after answering their question, even if correct.","id":"witch"},{"name":"Zealot","align":"good","text":"Only 1 jinxed character can be in play.","id":"zealot"},{"name":"Bloodnote","align":"good","text":"After a player answers a question correctly, they still die, regardless of the { } text.","id":"bloodnote_scp_fragmented_veil"},{"name":"Pipe Maze","align":"evil","text":"If a player would die during the day except by answering a question incorrectly, it follows the Pipemaze''s rule.","slug":"pipe-maze"},{"name":"Sauelsuesor","align":"good","text":"Players killed by the Sauelsuesor answering their question correctly register as nominated by them.","slug":"sauelsuesor"},{"name":"Tunisian","align":"good","text":"The Tunisian-protected-good-players cannot die from players answering their question correctly.","slug":"tunisian"},{"name":"Peacemonger","align":"good","text":"If no good player answers a question correctly during the day, the Peacemonger''s ability will activate.","slug":"peacemonger-scp-fragmented-veil"},{"name":"Immaterial","align":"good","text":"If the Immaterial would die during the day, they might live and kill a teammate tonight.","slug":"immaterial"},{"name":"Revenant","align":"good","text":"If the Abysewhell is in play & the Revenant dies during the day by a player answering their question correctly, they wake that night to use their ability. They are drunk if their killer is good.","slug":"revenant-scp-fragmented-veil"},{"name":"GOC Physics","align":"good","text":"GOC Physics cannot die from evil players answering their question correctly whilst they activated their ability last night.","slug":"goc-physics"},{"name":"Autarch","align":"evil","text":"Players who answer a question, whether they are right or wrong, register as having nominated to the Autarch.","id":"autarch_hblreleased"},{"name":"Crawler","align":"evil","text":"Only 1 jinxed character can be in play.","id":"crawler_hblreleased"},{"name":"Chupacabra","align":"evil","text":"If the Abysewhell is in play, the Chupacabra can only choose to kill players that killed evil players today by answering correctly today.","id":"chupacabra_hblreleased"},{"name":"Fetch","align":"good","text":"The 1st player who dies during the day registers as executed to the Fetch.","id":"fetch_hblreleased"},{"name":"Haberdasher","align":"good","text":"Only 1 jinxed character can be in play.","id":"haberdasher_hblreleased"},{"name":"Moonflower","align":"good","text":"Players who die by a good player answering their question correctly register as executed to the Moonflower.","id":"moonflower_hblreleased"},{"name":"Porcher","align":"good","text":"Only 1 jinxed character can be in play.","id":"porcher_hblreleased"},{"name":"Rancher","align":"good","text":"Evil players that die to a good player answering their question correctly register as executed to the Rancher.","id":"rancher_hblreleased"},{"name":"Seraph","align":"good","text":"Good players who die by the Seraph answering their question correctly register as executed to the Seraph.","id":"seraph_hblreleased"},{"name":"Vampire","align":"evil","text":"If the Abysewhell is in play & an evil player would kill another evil player by answering their question correctly, the victim lives. If a Townsfolk chooses to kill the Vampire by answering their question correctly, both players are poisoned until dawn, even if the Vampire dies.","id":"vampire_hblreleased"},{"name":"Wig Snatcher","align":"good","text":"Players who die by a evil player answering their question correctly register as dieing at night to the Wig Snatcher.","id":"wigsnatcher_hblreleased"},{"name":"Archivist","align":"good","text":"Each day, the Archivist may ask a yes/no question about a question that a player received. This answer is arbitrary is that player is not evil.","id":"archivist_the_bootleggers_anthology"},{"name":"Cardinal","align":"good","text":"If the Abysewhell is in play, & the Cardinal is chosen by a player answering their question correctly, their alignment becomes opposite to whoever chose them, even as they die.","id":"cardinal_the_bootleggers_anthology"},{"name":"Deserter","align":"good","text":"Only 1 jinxed character can be in play.","id":"deserter_the_bootleggers_anthology"},{"name":"Fencer","align":"good","text":"The Fencer''s ability is replaced with ''Once per game, during the day, visit the Storyteller to learn the answer to a future question.''","id":"fencer_the_bootleggers_anthology"},{"name":"Firebrand","align":"good","text":"If the Abysewhell is in play & the Firebrand draws first blood (killing another player by answering correctly) and survives, they''ll use their ability tonight.","id":"firebrand_the_bootleggers_anthology"},{"name":"Local Hero","align":"good","text":"If the Abysewhell is in play & an evil player kills the Local Hero by answering their question correctly, the character they know dies tonight.","id":"localhero_the_bootleggers_anthology"},{"name":"Penitent","align":"good","text":"If the Abysewhell is in play & the Penitent dies and the Abysewhell chooses to change their ability whilst dead, a living Minion gets it instead and becomes \"the Demon\".","id":"penitent_the_bootleggers_anthology"},{"name":"Spice Trader","align":"good","text":"Players that answer questions register as voting to the Spice Trader.","id":"spicetrader_the_bootleggers_anthology"},{"name":"Steeplejack","align":"good","text":"If the Abysewhell is in play & the Steeplejack dies during the day by a player answering their question correctly, they wake that night to use their ability. They are drunk if their killer is good.","id":"steeplejack_the_bootleggers_anthology"},{"name":"Silversmith","align":"good","text":"If the Abysewhell is in play & only 3 players live on the final day, the Silversmith may suggest a question to the Storyteller they''ll use.","id":"silversmith_the_bootleggers_anthology"},{"name":"Warden","align":"evil","text":"If the Abysewhell is in play & an evil player would kill the player the Warden chose by answering their question correctly, that player does not die.","id":"warden_the_bootleggers_anthology"},{"name":"Wight","align":"evil","text":"The Wight & ''cursed'' players ''curse'' whoever kills it by answering their question correctly, up to 2 people. Cursed Townsfolk are poisoned.","id":"wight_the_bootleggers_anthology"},{"name":"Carpenter","align":"evil","text":"The Carpenter instead learns how many alive neighbours of evil players died today.","id":"carpenter_circus_music"}],"customBoxes":[{"title":"More jinxes","content":"**Cleric:** If the Abysewhell is in play & the Cleric kills an evil player by answering their question whilst they have their ability, good wins.\n\n**Kenku:** If the Abysewhell is in play & a Kenku-protected-players would die from an evil player answering their question correctly, 2 other good players die instead.\n\n**Shade:** If the Abysewhell is in play & the Shade answers a question, right or wrong, their might ability activate on the most recent good winner.\n\n**Bug Keeper:** Players who choose the Bug Keeper by answering correctly register as having nominated them.\n\n**Firewatcher:** If a Firewatcher-protected-player would die from an evil player answering their question correctly, they die instead & the day ends.\n\n**Vixin:** If the Abysewhell is in play & the Vixin dies to a good player answering their question correctly, their ability activates tonight.\n\n**Junkbug:** If the Junkbug correctly answers a question & chooses to kill an evil player, their ability activates to drunken a player.\n\n**Trapsmith:** If an evil player kills the Trapsmith-protected player by answering their question correctly, they are told to pick again.\n\n**Buggane:** Only 1 jinxed character can be in play.\n\n**Carpenter:** If a good player kills the Carpenter by answering their question correctly, they become a not-in-play evil Minion tonight.\n\n**Escape Artist:** The Escape Artist''s ability is replaced with \"If chosen by an player answering their question correctly, before you die, you may publicly ask for a question. If correct & they oppose them, they also die.\".\n\n**Lemming:** If the Abysewhell is in play & the Lemming is chosen by a good player answering their ability, they become a Lemming and not all Lemmings die to their ability.\n\n**Milkmaid:** If the Abysewhell is in play & the Milkmaid dies during the day by a player answering their question correctly, they wake that night to use their ability. They are drunk if their killer is good.\n\n**Rat-Catcher:** If the Abysewhell is in play & the Rat-Catcher dies during the day by an player answering their question correctly, an alive evil player gains the ability \"Good wins if just 3 players live. The Demon knows who you are\". They are drunk if their killer is good.\n\n**Schemester:** Only 1 jinxed character can be in play.\n\n**Scorpion:** Players that die to a good player answering their question correctly register as executed to the Scorpion.\n\n**Troll:** If the Abysewhell is in play & an evil player kills the Troll by answering their question correctly, an evil player dies instead (unless the Troll is drunk).\n\n**Vicar:** Vicar-protected-players cannot die from evil players answering their question correctly.\n\n**White Elephant:** If the Abysewhell is in play & the White Elephants dies to a good player answering their question correctly, they register as executed.\n\n**Akiryo:** Good players who die by another good player answering their question correctly register as executed to the Akiryo.\n\n**Anthropologist:** If both the Abysewhell & Anthropologist are in play & no one claimed their character before the day ended, evil wins tonight.\n\n**Baker:** Baker-protected-players cannot die from evil players answering their question correctly.\n\n**Bloodless:** Only 1 jinxed character can be in play.\n\n**Bog Dweller:** If the Abysewhell is in play & the Bogdweller is chosen by a player answering their question correctly, their ability activates tonight.\n\n**Breathsnatch:** Evil players that die to a good player answering their question correctly register as executed to the Breathsnatch.\n\n**Child of Lir:** Only 1 jinxed character can be in play.\n\n**Dockworker:** If the Abysewhell is in play & an evil player would be killed by a player answering their question correctly, they register as an executed Demon to the Dockworker.\n\n**Guilt:** Players who kill other players by answering their question correctly register as having nominated & executed to the Guilt.\n\n**Haunt:** If the Abysewhell is in play & the Haunt or their victim are killed by a good player answering their question correctly, all players learn this.\n\n**Heir:** Only 1 jinxed character can be in play.\n\n**Houndmaster:** If the Abysewhell is in play & the Houndmaster choose an evil player when answering their question correctly, their ability activates tonight.\n\n**Justice:** Only 1 jinxed character can be in play.\n\n**Maskbearer:** Maskbearer-protected-players cannot die from players answering their question correctly.\n\n**Moonshiner:** If the Abysewhell is in play & the Moonshiner is chosen by a player answering their question correctly, they are drunk until dawn, even if the Moonshiner dies.\n\n**Mourner:** Players killed by a player answering their question correctly register as executed to the Mourner.\n\n**Wayfarer:** If the Abysewhell is in play, the Wayfarer instead learns if the chosen player has killed an evil player by answering their question correctly."}],"firstNight":0,"otherNight":0,"setup":false,"special":[{"name":"pointing","type":"ability","time":"day"}],"art":"art/abysewhell.png","jsonId":"abysewhell_scp_fragmented_veil","curata":false}','scp-fragmented-veil/abysewhell','published',datetime('now'),datetime('now'));
